library(tidyverse)
library(plotly)

full_data &lt;- read_csv("../data/combined_data.csv", show_col_types = FALSE) |&gt;
  filter(month &gt;= as.Date("2024-12-01")) |&gt;  # Exclude partial November 2024.
  arrange(month, State) |&gt;
  mutate(
    month_label = format(month, "%Y-%m"),
    hover_label = paste0(
      State, "&lt;br&gt;Month: ", month_label,
      "&lt;br&gt;Hours for 15 gallons: ", round(hours_per_fillup, 2),
      "&lt;br&gt;Real gas price: $", round(MRA_Regular, 2), "/gallon"
    )
  )
